  const [sentIdx, setSentIdx]   = useState<number | null>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, loading]);

  async function handleSendToSlack(report: Report, idx: number) {
    setSending(true);
    try {
      const res  = await fetch("/api/send-slack", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ report }),
      });
      const data = await res.json();
      if (data.ok) setSentIdx(idx);
      else setMessages((prev) => [...prev, { role: "assistant", text: `❌ ${data.error}` }]);
    } catch {
      setMessages((prev) => [...prev, { role: "assistant", text: "❌ Failed to send to Slack." }]);
    } finally {
      setSending(false);
